from __future__ import annotations

from fastapi import Query, Request
from fastapi.responses import HTMLResponse
import app as core

app = core.app

# Request-mode safety improvement:
# The normal uploader already trims/pads AI-cleaned assets. For request storefronts,
# do the same safe transparent-padding trim for the original path too, so using
# "Use Original" still creates a properly normalized storefront logo.
def _request_build_original_assets(session_id: str):
    p = core._paths(session_id)
    master = core.Image.open(p["orig_master"]).convert("RGBA")
    original_final = core._normalize_logo(master, target_size=core.TARGET_PX)
    original_preview = core._center_preview(original_final, canvas_size=core.PREVIEW_PX)
    core._save_png(original_preview, p["orig_preview"])
    core._save_png(original_final, p["orig_curr"])

core._build_original_assets = _request_build_original_assets

app.router.routes = [
    r for r in app.router.routes
    if not (getattr(r, 'path', None) == '/ui' and 'GET' in getattr(r, 'methods', set()))
]


@app.get('/ui', response_class=HTMLResponse)
def request_mode_ui(
    request: Request,
    embed: int = Query(0),
    return_mode: str = Query('postmessage', alias='return'),
    slot: str = Query('main'),
    return_to: str = Query('', alias='return_to'),
    session_id: str = Query('', alias='session_id'),
    mode: str = Query('request'),
    autopick: int = Query(0),
):
    html = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=0"><title>Studio Uploader</title><style>
:root{--bg:#050505;--line:rgba(255,255,255,.12);--muted:rgba(255,255,255,.62);--gold:#b7a36a;--blue:#168bf2;--green:#10b981;--danger:#ef4444}*{box-sizing:border-box}html,body{height:100%;margin:0;overflow:hidden;background:var(--bg);color:#fff;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,sans-serif}.app{height:100dvh;display:grid;grid-template-rows:auto 1fr auto;background:radial-gradient(circle at 10% -10%,rgba(183,163,106,.18),transparent 35%),#050505}.top{height:54px;display:flex;align-items:center;justify-content:space-between;padding:0 16px;background:#101010;border-bottom:1px solid var(--line)}.title{font-size:15px;font-weight:950}.x{width:38px;height:38px;border-radius:12px;border:1px solid var(--line);background:rgba(255,255,255,.08);color:#fff;font-size:18px;cursor:pointer}.main{min-height:0;padding:12px;display:flex;align-items:center;justify-content:center}.upload,.review{width:min(1120px,100%);height:100%;max-height:calc(100dvh - 122px);border:1px solid var(--line);border-radius:22px;background:#000;overflow:hidden;display:flex;flex-direction:column}.upload{align-items:center;justify-content:center;gap:10px;border-style:dashed;position:relative}.upload input{position:absolute;inset:0;opacity:0}.upload h1{font-size:18px;margin:0}.upload p{margin:0;color:var(--muted);font-size:13px}.folder{font-size:42px}.busy{position:absolute;inset:0;display:none;align-items:center;justify-content:center;text-align:center;background:rgba(0,0,0,.88);padding:24px;z-index:5}.busy.on{display:flex}.busyBox{display:grid;gap:10px;place-items:center}.spin{width:34px;height:34px;border-radius:50%;border:3px solid rgba(255,255,255,.2);border-top-color:#fff;animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.busyTitle{font-weight:950;font-size:16px}.busySub{color:var(--muted);font-size:13px}.review{display:none}.review.on{display:flex}.upload.off{display:none}.previewWrap{min-height:0;flex:1;display:flex;padding:10px}.stage{flex:1;border-radius:16px;border:1px solid var(--line);background:#fff;display:flex;align-items:center;justify-content:center;overflow:hidden}.stage.grid{background-color:#fff;background-image:linear-gradient(45deg,#e9edf3 25%,transparent 25%),linear-gradient(-45deg,#e9edf3 25%,transparent 25%),linear-gradient(45deg,transparent 75%,#e9edf3 75%),linear-gradient(-45deg,transparent 75%,#e9edf3 75%);background-size:22px 22px;background-position:0 0,0 11px,11px -11px,-11px 0}.stage.dark{background:#101827}.stage img{max-width:90%;max-height:90%;object-fit:contain}.compare{display:none;gap:10px;width:100%;height:100%}.compare.on{display:flex}.choice{flex:1;border:2px solid transparent;border-radius:14px;background:#fff;position:relative;display:flex;align-items:center;justify-content:center;overflow:hidden;cursor:pointer}.choice.dark{background:#101827}.choice.selected{border-color:var(--blue)}.choice img{max-width:88%;max-height:88%;object-fit:contain}.choice span{position:absolute;left:10px;top:10px;border-radius:999px;background:#111;color:#fff;padding:6px 9px;font-size:12px;font-weight:900}.tools{padding:9px 10px;border-top:1px solid var(--line);display:grid;gap:8px}.row{display:flex;gap:8px;justify-content:center;flex-wrap:wrap}.pill,.btn,.done,.change{border:0;cursor:pointer;font-weight:950}.pill{border-radius:10px;background:#252525;color:#fff;padding:8px 12px}.pill.active{background:#fff;color:#111}.btn{border-radius:12px;min-height:42px;padding:10px 14px;color:#fff}.btn.original{background:#303033;flex:1}.btn.ai{background:var(--blue);flex:1}.status{min-height:18px;text-align:center;font-size:12px;color:var(--muted);font-weight:800}.status.bad{color:#fecaca}.status.good{color:#bbf7d0}.bottom{padding:9px 12px;border-top:1px solid var(--line);display:flex;gap:10px;align-items:center;background:#0b0b0a}.change{border-radius:999px;background:rgba(255,255,255,.08);color:#fff;padding:0 14px;min-height:38px}.done{margin-left:auto;border-radius:999px;min-height:42px;padding:0 20px;background:linear-gradient(135deg,#111,#3b3118 58%,#6f5a2a);color:#fff}.done:disabled{opacity:.42}.tiny{font-size:12px;color:var(--muted);font-weight:750}@media(max-width:760px){.top{height:50px}.main{padding:8px}.upload,.review{border-radius:16px;max-height:calc(100dvh - 108px)}.previewWrap{padding:8px}.compare.on{display:grid;grid-template-rows:1fr 1fr;gap:8px}.choice{width:100%;min-height:0}.choice span{font-size:11px;padding:5px 8px}.btn{width:100%;flex-basis:100%;min-height:40px}.bottom{padding:8px;gap:8px}.done{min-height:40px;padding:0 16px}.tiny{display:none}.change{min-height:38px;padding:0 12px}}
</style></head><body><div class="app"><div class="top"><div class="title">Logo Upload</div><button class="x" id="closeBtn" type="button">×</button></div><main class="main"><label class="upload" id="uploadPane"><input id="fileInput" type="file" accept="image/png,image/jpeg,image/webp"><div class="folder">📁</div><h1>Choose your logo</h1><p>PNG, JPG, or WebP · max 12 MB</p><div class="busy" id="busyPane"><div class="busyBox"><div class="spin"></div><div class="busyTitle">Checking image & removing padding…</div><div class="busySub">This keeps your logo true to size on the shirt.</div></div></div></label><section class="review" id="reviewPane"><div class="previewWrap"><div class="stage grid" id="stage"><img id="mainPreview"></div><div class="compare" id="comparePane"><button class="choice" id="choiceOriginal" type="button"><span>Original</span><img id="origPreview"></button><button class="choice dark" id="choiceProcessed" type="button"><span>AI Cleaned</span><img id="aiPreview"></button></div></div><div class="tools"><div class="row"><button class="pill active" data-bg="grid" type="button">Grid</button><button class="pill" data-bg="white" type="button">White</button><button class="pill" data-bg="dark" type="button">Dark</button></div><div class="row"><button class="btn original" id="useOriginal" type="button">Use Original</button><button class="btn ai" id="aiBtn" type="button">Send for AI Cleanup</button></div><div class="status" id="statusText">Choose original or use AI cleanup before continuing.</div></div></section></main><div class="bottom"><button class="change" id="changeBtn" type="button">Change file</button><div class="tiny" id="bottomNote">Pick the final version for your storefront.</div><button class="done" id="doneBtn" type="button" disabled>Done →</button></div></div><script>
const P=new URLSearchParams(location.search),AUTOPICK=P.get('autopick')==='1',RETURN_MODE=P.get('return')||'postmessage',SLOT=P.get('slot')||'main';
const fileInput=document.getElementById('fileInput'),uploadPane=document.getElementById('uploadPane'),reviewPane=document.getElementById('reviewPane'),stage=document.getElementById('stage'),mainPreview=document.getElementById('mainPreview'),origPreview=document.getElementById('origPreview'),aiPreview=document.getElementById('aiPreview'),comparePane=document.getElementById('comparePane'),choiceOriginal=document.getElementById('choiceOriginal'),choiceProcessed=document.getElementById('choiceProcessed'),useOriginal=document.getElementById('useOriginal'),aiBtn=document.getElementById('aiBtn'),doneBtn=document.getElementById('doneBtn'),statusText=document.getElementById('statusText'),bottomNote=document.getElementById('bottomNote'),busyPane=document.getElementById('busyPane');
let sessionId='',selectedVersion='',processedReady=false;function abs(path){return new URL(path,location.origin).toString()}function status(t,c=''){statusText.textContent=t;statusText.className='status '+c}function busy(on){busyPane.classList.toggle('on',!!on)}function show(){busy(false);uploadPane.classList.add('off');reviewPane.classList.add('on')}function selected(v){selectedVersion=v;doneBtn.disabled=false;choiceOriginal.classList.toggle('selected',v==='original');choiceProcessed.classList.toggle('selected',v==='processed');status(v==='processed'?'AI cleaned logo selected.':'Original logo selected.','good');bottomNote.textContent='Ready — tap Done to return to the form.'}function bg(v){document.querySelectorAll('.pill').forEach(b=>b.classList.toggle('active',b.dataset.bg===v));stage.className='stage '+(v==='dark'?'dark':v==='grid'?'grid':'');choiceOriginal.classList.toggle('dark',v==='dark');choiceProcessed.classList.toggle('dark',v==='dark')}
async function upload(file){if(!file)return;busy(true);const fd=new FormData();fd.append('file',file);const r=await fetch('/upload',{method:'POST',body:fd});if(!r.ok)throw new Error('upload failed');const d=await r.json();sessionId=d.session_id;selectedVersion='';processedReady=false;doneBtn.disabled=true;const u=abs(d.preview_original_url||('/preview/'+sessionId+'?version=original'));mainPreview.src=u;origPreview.src=u;comparePane.classList.remove('on');stage.style.display='flex';show();status('Padding removed. Choose original or send it for AI cleanup before continuing.')}
async function chooseOriginal(){if(!sessionId)return;status('Selecting original…');const r=await fetch('/set-active/'+sessionId+'?version=original',{method:'POST'});if(!r.ok)throw new Error('select failed');mainPreview.src=abs('/preview/'+sessionId+'?version=original&t='+Date.now());selected('original')}
async function processAI(){if(!sessionId)return;aiBtn.disabled=true;useOriginal.disabled=true;status('Cleaning background with AI…');const r=await fetch('/process/'+sessionId,{method:'POST'});if(!r.ok){aiBtn.disabled=false;useOriginal.disabled=false;throw new Error('process failed')}pollAI()}
function pollAI(){let tries=0;const timer=setInterval(async()=>{tries++;try{const r=await fetch('/session-info/'+sessionId+'?t='+Date.now());const s=await r.json();if(s.status==='failed'){clearInterval(timer);aiBtn.disabled=false;useOriginal.disabled=false;status('AI cleanup failed. You can still use the original.','bad');return}if(s.processed_available||s.active_version==='processed'){clearInterval(timer);processedReady=true;aiPreview.src=abs('/preview/'+sessionId+'?version=processed&t='+Date.now());mainPreview.src=aiPreview.src;stage.style.display='none';comparePane.classList.add('on');aiBtn.disabled=false;useOriginal.disabled=false;selected('processed');return}status('AI cleanup working… '+(s.stage||'processing'))}catch(e){}if(tries>90){clearInterval(timer);aiBtn.disabled=false;useOriginal.disabled=false;status('AI cleanup is taking too long. Use original or try again.','bad')}},1000)}
async function chooseProcessed(){if(!sessionId||!processedReady)return;const r=await fetch('/set-active/'+sessionId+'?version=processed',{method:'POST'});if(!r.ok)throw new Error('select failed');selected('processed')}
async function finish(){if(!sessionId||!selectedVersion){status('Choose your final logo before continuing.','bad');return}doneBtn.disabled=true;status('Saving final logo…');const r=await fetch('/finalize/'+sessionId,{method:'POST'});if(!r.ok){doneBtn.disabled=false;status('Choose your final logo before continuing.','bad');return}const d=await r.json();const payload={type:'studio-uploader:done',slot:SLOT,session_id:sessionId,filename:'storefront_logo.png',mime:'image/png',finalize_url:abs(d.finalize_url||('/finalize/'+sessionId)),final_image_url:abs(d.final_image_url||('/final-file/'+sessionId)),active_version:d.active_version||selectedVersion};if(RETURN_MODE==='postmessage'&&window.parent)window.parent.postMessage(payload,'*');else location.href=P.get('return_to')||'/'}
fileInput.addEventListener('change',()=>upload(fileInput.files&&fileInput.files[0]).catch(()=>{busy(false);status('Upload failed. Please try another image.','bad')}));useOriginal.addEventListener('click',()=>chooseOriginal().catch(()=>status('Could not select original.','bad')));aiBtn.addEventListener('click',()=>processAI().catch(()=>status('AI cleanup failed. You can use original.','bad')));choiceOriginal.addEventListener('click',()=>chooseOriginal().catch(()=>status('Could not select original.','bad')));choiceProcessed.addEventListener('click',()=>chooseProcessed().catch(()=>status('Could not select AI version.','bad')));doneBtn.addEventListener('click',finish);document.getElementById('changeBtn').addEventListener('click',()=>fileInput.click());document.getElementById('closeBtn').addEventListener('click',()=>{if(window.parent)window.parent.postMessage({type:'studio-uploader:close'},'*')});document.querySelectorAll('.pill').forEach(b=>b.addEventListener('click',()=>bg(b.dataset.bg)));if(AUTOPICK)setTimeout(()=>fileInput.click(),450);
</script></body></html>'''
    return HTMLResponse(html)
